public interface IEntity { string Id { get; } }

public sealed class Repository<T> where T : class, IEntity
{
    private readonly Dictionary<string, T> _items = new();
    public void Upsert(T item) => _items[item.Id] = item;          // IEntity gives us Id
    public T? Find(string id) => _items.GetValueOrDefault(id);     // class makes T? mean "or null"
}

public static T Max<T>(IEnumerable<T> items) where T : IComparable<T>
{
    using var e = items.GetEnumerator();
    if (!e.MoveNext()) throw new InvalidOperationException("empty");
    var best = e.Current;
    while (e.MoveNext())
        if (e.Current.CompareTo(best) > 0) best = e.Current;
    return best;
}
